style.css:
@-moz-document domain("faceit.com") {
/* Основной фон сайта – глубокий фиолетовый */
    body,
    .site-container,
    .page-wrap,
    .background__main {
        background-color: #0a0718 !important;
    }

    /* Карточки, панели, блоки матчей – тёмный фиолет с лёгкой подсветкой */
    .card,
    .match-room-card,
    .info-card,
    .panel,
    .content-box,
    .card-body,
    .profile-card,
    .stat-card,
    .match-list-item,
    .table-row,
    .hub-preview,
    .tournament-card,
    .league-card {
        background-color: #120c2b !important;
        border-color: #2a1e55 !important;
        box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4) !important;
    }

    /* Акцентные элементы – приятный мягкий фиолет */
    a,
    .link,
    .btn-link,
    .accent-text,
    .elo-value,
    .stat-value,
    .match-score-winner,
    .team-name {
        color: #c084fc !important;
    }

    /* Кнопки с фиолетовым акцентом */
    .btn-primary,
    button[type="submit"],
    .button--primary,
    .match-join-button,
    .action-button {
        background-color: #7c3aed !important;
        border-color: #a855f7 !important;
        color: #f3e8ff !important;
        transition: all 0.2s ease !important;
    }

    .btn-primary:hover,
    button[type="submit"]:hover,
    .button--primary:hover {
        background-color: #8b5cf6 !important;
        border-color: #c084fc !important;
        box-shadow: 0 0 8px rgba(139, 92, 246, 0.5) !important;
    }

    /* Поля ввода – тёмные, с фиолетовой каймой при фокусе */
    input,
    textarea,
    select,
    .input-field,
    .search-input {
        background-color: #0f0922 !important;
        border: 1px solid #2a1e55 !important;
        color: #e2e2ff !important;
    }

    input:focus,
    textarea:focus,
    select:focus {
        border-color: #a855f7 !important;
        outline: none !important;
        box-shadow: 0 0 6px #7c3aed !important;
    }

    /* Текст – светлый, легко читается на тёмном фоне */
    body,
    p,
    span,
    div,
    li,
    .text-default,
    .username,
    .nickname,
    .match-player-name {
        color: #ddd9ff !important;
    }

    /* Заголовки – более яркие */
    h1, h2, h3, h4, .heading,
    .match-score,
    .match-map-name {
        color: #e9d5ff !important;
    }

    /* Полоски прогресса, рейтинг, ELO — фиолетовый градиент */
    .progress-bar,
    .elo-progress,
    .stat-bar-fill {
        background: linear-gradient(90deg, #7c3aed, #c084fc) !important;
    }

    /* Скролл бар (приятный, не режет глаз) */
    ::-webkit-scrollbar {
        width: 8px;
        height: 8px;
    }

    ::-webkit-scrollbar-track {
        background: #0a0718 !important;
    }

    ::-webkit-scrollbar-thumb {
        background: #4c1d95 !important;
        border-radius: 10px !important;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: #7c3aed !important;
    }

    /* Выделение текста */
    ::selection {
        background: #7c3aed !important;
        color: #ffffff !important;
    }

    /* Таблицы, строки четные/нечетные */
    .table-striped tbody tr:nth-of-type(odd),
    .match-list-item:nth-child(even) {
        background-color: #0e0820 !important;
    }

    /* Дропдауны и меню */
    .dropdown-menu,
    .select-dropdown {
        background-color: #120c2b !important;
        border-color: #2a1e55 !important;
    }

    /* Иконки (убираем инверсию, если нужно — оставляем светлыми) */
    svg:not([fill="none"]) {
        fill: #c084fc !important;
    }

    /* Чат, сообщения пользователей */
    .chat-message,
    .message-line {
        background-color: #0f0922 !important;
        border-left: 3px solid #7c3aed !important;
        color: #d9d3ff !important;
    }

    /* Участники матча, авы, рамки */
    .player-avatar,
    .team-logo {
        border-color: #7c3aed !important;
    }
}
